import * as PIXI from 'pixi.js';

/**
 * Loader for the ROM-extracted sprite atlas (sprites/atlas.png + atlas.json,
 * generated by robotron-re/tools/build_atlas.py).
 *
 * Frames are named `<family>_<index>` with indices in original ROM order,
 * which is animation order (walk cycles are stored consecutively in ROM).
 * Families: grunt, mutant, hulk, spheroid, spark, brain, player, human,
 * burst, quark, misc_late.
 */

interface AtlasFrame { x: number; y: number; w: number; h: number; }
interface AtlasMeta { palette: number[][]; frames: Record<string, AtlasFrame>; }

let baseTexture: PIXI.TextureSource | null = null;
let meta: AtlasMeta | null = null;
const textureCache = new Map<string, PIXI.Texture>();

export const ArcadeAtlas = {
    async load(): Promise<void> {
        if (meta) return;
        // Fetch metadata first (never from cache), then load the sheet keyed
        // by the metadata's build version — a cached atlas.png from an older
        // build paired with fresh JSON puts every frame rect on the wrong
        // sprite (electrodes wearing grunt frames, etc.).
        meta = await (await fetch('sprites/atlas.json', { cache: 'no-store' })).json();
        const sheet = await PIXI.Assets.load(`sprites/atlas.png?v=${(meta as any).version ?? 0}`);
        sheet.source.scaleMode = 'nearest';
        baseTexture = sheet.source;
    },

    isLoaded(): boolean { return meta !== null; },

    /** Texture for a named frame, e.g. 'grunt_3'. Returns null if unknown. */
    texture(name: string): PIXI.Texture | null {
        if (!meta || !baseTexture) return null;
        const cached = textureCache.get(name);
        if (cached) return cached;
        const f = meta.frames[name];
        if (!f) return null;
        const tex = new PIXI.Texture({
            source: baseTexture,
            frame: new PIXI.Rectangle(f.x, f.y, f.w, f.h),
        });
        textureCache.set(name, tex);
        return tex;
    },

    /** All textures of a family in ROM (= animation) order. */
    frames(family: string): PIXI.Texture[] {
        if (!meta) return [];
        const names = Object.keys(meta.frames)
            .filter(n => n.startsWith(family + '_'))
            .sort((a, b) => parseInt(a.slice(family.length + 1)) - parseInt(b.slice(family.length + 1)));
        return names.map(n => this.texture(n)!).filter(Boolean);
    },

    /** The 16-entry Williams palette captured from hardware (RGB triples). */
    palette(): number[][] { return meta?.palette ?? []; },
};
